-- 帮助文档表
CREATE TABLE IF NOT EXISTS `sys_help_doc` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `doc_key` varchar(100) NOT NULL COMMENT '文档标识（如：采购单、库存盘点、发货计划等）',
  `title` varchar(200) NOT NULL COMMENT '文档标题',
  `content` text NOT NULL COMMENT '文档内容（Markdown格式）',
  `category` varchar(50) DEFAULT NULL COMMENT '分类（如：erp、amazon、finance、setting等）',
  `keywords` varchar(500) DEFAULT NULL COMMENT '关键词（逗号分隔，用于搜索）',
  `related_docs` varchar(500) DEFAULT NULL COMMENT '关联文档（逗号分隔的doc_key）',
  `sort_order` int(11) DEFAULT 0 COMMENT '排序号',
  `status` tinyint(1) DEFAULT 1 COMMENT '状态（1：启用，0：禁用）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_key` (`doc_key`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='帮助文档表';

-- 插入帮助文档数据
INSERT INTO `sys_help_doc` (`doc_key`, `title`, `content`, `category`, `keywords`, `related_docs`, `sort_order`) VALUES
('purchase', '采购管理', '## 采购管理模块\n\n### 功能概述\n采购管理模块用于管理采购订单的全生命周期，包括创建采购单、审核、入库等操作。\n\n### 主要功能\n1. **采购单列表**：查看所有采购订单\n2. **新建采购单**：创建采购订单\n3. **采购单详情**：查看采购单详细信息\n4. **采购入库**：执行入库操作\n\n### 操作指南\n\n#### 创建采购单\n1. 进入 ERP > 采购 > 采购单列表\n2. 点击「新建采购单」按钮\n3. 选择供应商\n4. 添加采购商品（输入SKU或名称搜索）\n5. 填写采购数量和单价\n6. 选择入库仓库\n7. 保存并提交审核\n\n#### 采购入库\n1. 在采购单列表找到待入库的采购单\n2. 点击「入库」按钮\n3. 确认入库数量\n4. 选择库位\n5. 提交入库\n\n### 注意事项\n- 采购单需要审核后才能入库\n- 可以批量添加商品\n- 入库时可以修改实际入库数量\n\n### 相关模块\n- 库存管理：查看入库后的库存\n- 供应商管理：管理供应商信息\n- 财务模块：采购付款', 'erp', '采购,purchase,供应商,入库,采购单', 'inventory,supplier,finance', 1),
('inventory', '库存管理', '## 库存管理模块\n\n### 功能概述\n库存管理模块用于查看和管理ERP系统中的库存信息，包括库存查询、库存变动记录、库存预警等。\n\n### 主要功能\n1. **库存列表**：查看各仓库的库存情况\n2. **库存明细**：查看SKU级别的库存详情\n3. **库存变动记录**：查看库存进出历史\n4. **库存预警**：低库存预警提醒\n\n### 操作指南\n\n#### 查看库存\n1. 进入 ERP > 库存 > 库存列表\n2. 选择仓库（可选）\n3. 输入SKU或商品名称搜索\n4. 查看库存数量和分布\n\n#### 查看库存变动\n1. 在库存列表点击某个SKU\n2. 查看库存变动记录\n3. 可以按时间范围筛选\n\n### 注意事项\n- 库存数据实时更新\n- 可以导出库存报表\n- 支持多仓库管理\n\n### 相关模块\n- 采购管理：采购入库增加库存\n- 发货管理：发货出库减少库存\n- 盘点管理：库存盘点调整', 'erp', '库存,inventory,仓库,SKU,库存预警', 'purchase,shipment,stocktake', 2),
('stocktake', '库存盘点', '## 库存盘点模块\n\n### 功能概述\n库存盘点模块用于定期盘点实际库存与系统库存的差异，并进行调整。\n\n### 主要功能\n1. **盘点单列表**：查看所有盘点单\n2. **新建盘点单**：创建盘点任务\n3. **录入盘点结果**：输入实际盘点数量\n4. **盘点差异处理**：调整库存差异\n\n### 操作指南\n\n#### 创建盘点单\n1. 进入 ERP > 库存 > 盘点管理\n2. 点击「新建盘点单」\n3. 选择盘点仓库\n4. 选择盘点范围（全盘/部分）\n5. 开始盘点\n\n#### 录入盘点结果\n1. 在盘点单详情页\n2. 逐个录入实际数量\n3. 系统自动计算差异\n4. 提交盘点结果\n\n#### 处理盘点差异\n1. 查看盘点差异报告\n2. 确认差异原因\n3. 提交调整\n4. 系统自动调整库存\n\n### 注意事项\n- 盘点期间建议暂停出入库操作\n- 差异会自动调整库存\n- 盘点单需要审核\n\n### 相关模块\n- 库存管理：查看调整后的库存\n- 财务模块：盘点损益处理', 'erp', '盘点,stocktake,库存盘点,盘点单', 'inventory', 3),
('shipment', '发货管理', '## 发货管理模块\n\n### 功能概述\n发货管理模块用于管理发货计划、物流跟踪、发货单等，支持发货到FBA仓库。\n\n### 主要功能\n1. **发货计划列表**：查看所有发货计划\n2. **新建发货计划**：创建发货任务\n3. **物流跟踪**：查看物流状态\n4. **发货单管理**：管理发货单据\n\n### 操作指南\n\n#### 创建发货计划\n1. 进入 ERP > 发货 > 发货计划\n2. 点击「新建发货计划」\n3. 选择目标站点和FBA仓库\n4. 添加发货商品和数量\n5. 选择物流渠道和物流公司\n6. 生成箱唛并打包\n7. 提交发货计划\n\n#### 物流跟踪\n1. 在发货计划列表\n2. 点击「查看详情」\n3. 查看物流跟踪信息\n\n### 注意事项\n- 确保FBA库存容量充足\n- 按照Amazon要求打包\n- 及时更新物流信息\n\n### 相关模块\n- 库存管理：发货出库\n- FBA库存：查看FBA库存\n- 物流渠道：配置物流渠道', 'erp', '发货,shipment,物流,FBA,发货计划', 'inventory,fba', 4),
('fba_inventory', 'FBA库存管理', '## FBA库存管理模块\n\n### 功能概述\nFBA库存管理模块用于查看Amazon FBA仓库的库存情况，包括库存数量、库存变动、库存预警等。\n\n### 主要功能\n1. **FBA库存列表**：查看各站点FBA库存\n2. **库存明细**：查看SKU级别的库存详情\n3. **库存变动记录**：查看库存进出历史\n4. **库存预警**：低库存预警提醒\n\n### 操作指南\n\n#### 查看FBA库存\n1. 进入 Amazon > 库存管理 > FBA库存\n2. 选择店铺和站点\n3. 查看库存列表\n4. 可以按SKU、ASIN搜索\n\n#### 查看库存变动\n1. 点击某个SKU\n2. 查看库存变动记录\n3. 可以按时间范围筛选\n\n### 注意事项\n- FBA库存数据有延迟（通常24小时）\n- 库存数量包括可售、不可售、预留等\n- 可以导出库存报表\n\n### 相关模块\n- 发货管理：发货到FBA\n- 订单管理：FBA订单\n- 广告管理：广告库存', 'amazon', 'FBA,库存,Amazon,站点,SKU,ASIN', 'shipment,order,advertising', 5),
('order', '订单管理', '## 订单管理模块\n\n### 功能概述\n订单管理模块用于查看和管理Amazon订单，包括订单列表、订单详情、退货订单等。\n\n### 主要功能\n1. **订单列表**：查看所有订单\n2. **订单详情**：查看订单详细信息\n3. **退货订单**：管理退货订单\n4. **订单统计**：订单数据统计\n\n### 操作指南\n\n#### 查看订单\n1. 进入 Amazon > 订单管理 > 订单列表\n2. 选择店铺和站点\n3. 设置日期范围\n4. 查看订单列表\n\n#### 查看订单详情\n1. 在订单列表点击某个订单\n2. 查看订单详细信息\n3. 包括商品、收货地址、物流等\n\n### 注意事项\n- 订单数据实时更新\n- 可以按状态筛选订单\n- 支持导出订单数据\n\n### 相关模块\n- FBA库存：FBA订单库存\n- 发货管理：自发货订单\n- 财务模块：订单结算', 'amazon', '订单,order,Amazon,退货,销售', 'fba_inventory,shipment,finance', 6),
('advertising', '广告管理', '## 广告管理模块\n\n### 功能概述\n广告管理模块用于管理Amazon广告投放，包括广告活动、广告组、关键词等。\n\n### 主要功能\n1. **广告活动列表**：查看所有广告活动\n2. **广告报表**：广告效果数据\n3. **关键词管理**：管理广告关键词\n4. **广告优化**：广告投放建议\n\n### 操作指南\n\n#### 查看广告活动\n1. 进入 Amazon > 广告管理 > 广告活动\n2. 选择店铺和站点\n3. 查看广告活动列表\n4. 可以按状态筛选\n\n#### 查看广告报表\n1. 进入 Amazon > 广告管理 > 广告报表\n2. 选择时间范围\n3. 查看广告效果数据\n4. 包括曝光、点击、花费、销售额等\n\n### 注意事项\n- 广告数据有延迟（通常24小时）\n- 可以按活动类型筛选\n- 支持导出报表\n\n### 相关模块\n- FBA库存：广告商品库存\n- 订单管理：广告订单\n- 财务模块：广告费用', 'amazon', '广告,advertising,PPC,关键词,广告活动', 'fba_inventory,order,finance', 7),
('finance', '财务管理', '## 财务管理模块\n\n### 功能概述\n财务管理模块用于管理财务凭证、科目余额、总账等财务数据。\n\n### 主要功能\n1. **凭证管理**：录入和审核凭证\n2. **科目余额**：查看科目余额表\n3. **总账**：查看总账明细\n4. **财务报表**：生成财务报表\n\n### 操作指南\n\n#### 录入凭证\n1. 进入 财务 > 凭证管理\n2. 点击「新增凭证」\n3. 填写凭证日期、摘要\n4. 添加会计分录\n5. 保存并审核\n\n#### 查看科目余额\n1. 进入 财务 > 科目余额\n2. 选择期间\n3. 查看科目余额表\n4. 可以导出报表\n\n### 注意事项\n- 凭证需要审核\n- 科目余额实时更新\n- 支持多期间查询\n\n### 相关模块\n- 采购管理：采购付款\n- 订单管理：销售收款\n- 结算报表：Amazon结算', 'finance', '财务,finance,凭证,科目,总账', 'purchase,order,settlement', 8),
('setting', '系统设置', '## 系统设置模块\n\n### 功能概述\n系统设置模块用于管理系统配置，包括用户管理、角色权限、店铺授权等。\n\n### 主要功能\n1. **用户管理**：管理系统用户\n2. **角色管理**：管理角色权限\n3. **店铺授权**：管理Amazon店铺授权\n4. **字典管理**：管理系统字典\n\n### 操作指南\n\n#### 用户管理\n1. 进入 设置 > 用户管理\n2. 查看用户列表\n3. 可以新增、编辑、删除用户\n4. 分配角色和权限\n\n#### 角色管理\n1. 进入 设置 > 角色管理\n2. 查看角色列表\n3. 配置角色权限\n4. 分配菜单权限\n\n#### 店铺授权\n1. 进入 设置 > 授权管理 > Amazon授权\n2. 查看授权列表\n3. 添加新店铺授权\n4. 刷新授权状态\n\n### 注意事项\n- 用户需要分配角色才能访问系统\n- 角色权限控制菜单和功能访问\n- 店铺授权需要定期刷新\n\n### 相关模块\n- 用户管理：用户账号\n- 角色管理：权限控制\n- 店铺管理：店铺配置', 'setting', '设置,setting,用户,角色,权限,授权', 'user,role,auth', 9);
